/** CZK arithmetic in integer halers, independent of VAT basis. */
const minor = (amount: string) => {
  const [whole = '0', fraction = ''] = amount.split('.');
  return BigInt(whole) * 100n + BigInt(fraction.padEnd(2, '0'));
};

export const calculateServiceOffer = (draft: OfferDraft) => {
  const total = [draft.work, draft.transport, draft.disposal, draft.material, draft.other].reduce(
    (sum, amount) => sum + minor(amount),
    0n,
  );
  return { ...draft, total: `${total / 100n}.${String(total % 100n).padStart(2, '0')}` };
};

